def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = me[-1]
    last_op = op[-1]
    if n == 1:
        return 'C' if last_op == 'C' else 'D'
    if n >= 99:
        return 'D'

    recent_len = min(12, n)
    recent_start = n - recent_len
    total_c = 0
    total_me_d = 0
    recent_c = 0
    for i in range(n):
        if op[i] == 'C':
            total_c += 1
            if i >= recent_start:
                recent_c += 1
        if me[i] == 'D':
            total_me_d += 1

    if total_c == 0:
        return 'D'
    if total_c == n and total_me_d > 0:
        return 'D'

    recent_ratio = recent_c / recent_len
    total_ratio = total_c / n

    run_op_d = 0
    run_dd = 0
    run_my_d = 0
    stop_op = False
    stop_dd = False
    stop_my = False
    for i in range(n - 1, -1, -1):
        o = op[i]
        m = me[i]
        if not stop_op:
            if o == 'D':
                run_op_d += 1
            else:
                stop_op = True
        if not stop_dd:
            if m == 'D' and o == 'D':
                run_dd += 1
            else:
                stop_dd = True
        if not stop_my:
            if m == 'D':
                run_my_d += 1
            else:
                stop_my = True
        if stop_op and stop_dd and stop_my:
            break

    myC_nextC = 0
    myC_nextD = 0
    myD_nextC = 0
    myD_nextD = 0
    mirror = 0
    for i in range(1, n):
        if me[i - 1] == 'C':
            if op[i] == 'C':
                myC_nextC += 1
            else:
                myC_nextD += 1
        else:
            if op[i] == 'C':
                myD_nextC += 1
            else:
                myD_nextD += 1
        if op[i] == me[i - 1]:
            mirror += 1
    mirror_rate = mirror / (n - 1) if n > 1 else 0.0

    if last_op == 'D':
        if last_me == 'C':
            if recent_ratio <= 0.20 and run_op_d >= 2:
                return 'D'
            if n >= 4 and myC_nextD >= 2 and myC_nextD >= myC_nextC + 1 and total_ratio < 0.75:
                return 'D'
            if run_op_d == 1 and recent_ratio >= 0.78:
                if rng.random() < 0.82:
                    return 'C'
                return 'D'
            if run_op_d == 1 and recent_ratio >= 0.62:
                if rng.random() < 0.65:
                    return 'C'
                return 'D'
            if run_op_d == 2 and recent_ratio >= 0.72:
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            if recent_ratio >= 0.48:
                if rng.random() < 0.20:
                    return 'C'
                return 'D'
            return 'D'
        else:
            if recent_ratio >= 0.62:
                return 'C'
            if run_dd <= 1 and total_ratio >= 0.55:
                return 'C'
            if mirror_rate >= 0.65 and recent_ratio >= 0.25 and run_dd <= 2:
                return 'C'
            if myC_nextC > myC_nextD and recent_ratio >= 0.25:
                if run_dd <= 2:
                    if rng.random() < 0.55:
                        return 'C'
                else:
                    if rng.random() < 0.25:
                        return 'C'
            if run_my_d >= 2 and recent_ratio >= 0.22 and myC_nextC >= myC_nextD:
                if rng.random() < 0.40:
                    return 'C'
            if n % 7 == 0 and total_ratio > 0.50 and recent_ratio > 0.20 and myC_nextC >= myC_nextD:
                return 'C'
            if run_dd >= 3 and total_ratio > 0.60 and recent_ratio > 0.08:
                if rng.random() < 0.12:
                    return 'C'
            return 'D'

    if last_me == 'D':
        if recent_ratio <= 0.25 and total_ratio <= 0.35:
            return 'D'
        if n >= 3 and myC_nextD >= myC_nextC + 1 and myD_nextC >= myD_nextD and total_ratio < 0.75:
            return 'D'
        if n == 98 and recent_ratio >= 0.55 and myD_nextC >= 2 and myD_nextD == 0:
            return 'D'
        return 'C'

    if recent_ratio <= 0.55 and total_ratio <= 0.55 and mirror_rate <= 0.55:
        return 'D'
    if n >= 5 and myC_nextD >= 2 and myC_nextD >= myC_nextC + 1 and recent_ratio < 0.80 and total_ratio < 0.75:
        return 'D'
    if n == 98 and myD_nextC >= 2 and myD_nextD == 0:
        return 'D'
    if n >= 22 and myD_nextC >= 3 and myD_nextD == 0 and recent_ratio >= 0.92:
        if rng.random() < 0.10:
            return 'D'
    return 'C'
